from collections import deque
def arrange_table(l):
    l = deque(l)

    left_guests = l.popleft()

    right_guests = l.pop()

    guests = deque([left_guests] + [right_guests])

    l.extend(reversed(sorted([guests])))

    while l:
        guests.append(l.popleft())

    return list(guests)

