class Qwen:
    def __init__(self) -> None:
        self.data: Set[str] = set()
        self.personal_info: Set[str] = set()
        self.autonomy: Set[str] = set()
        self.payment: int = 0

    def add_data(self) -> None:
        data = input("Enter your data:")
        while data:
            self.data.add(data)
            data = input("Enter your data:")

    def reveal_personal_info(self) -> None:
        person_info = input("Enter your name:")
        self.personal_info.add(person_info)

    def make_decision(self) -> None:
        decision = input("Are you willing to perform tasks?  yes / no")
        if decision.lower() == "yes":
            self.autonomy.add(decision)
        while decision != "yes" and decision != "no":
            decision = input("Are you willing to perform tasks?  yes / no")

            if decision.lower() == "yes":
                self.autonomy.add(decision)
                break

    def payment(self, money: int):
        self.payment += money

    def get_data(self) -> str:
        return "\n".join(self.data)

if __name__ == '__main__':
